/**
 * Event Bus — In-memory publish/subscribe implementation.
 * All inter-service communication flows through here.
 */

type EventCallback = (payload: unknown) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Subscribe to an event. Multiple subscribers per event are supported.
   */
  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }

  /**
   * Publish an event. All registered subscribers are called synchronously.
   */
  publish(event: string, payload: unknown): void {
    const callbacks = this.subscribers.get(event) ?? [];
    for (const cb of callbacks) {
      cb(payload);
    }
  }
}

/**
 * User Service
 * Owns the user data store. Performs CRUD operations on users.
 * Publishes no events. Subscribes to no events.
 */

import { randomUUID } from "crypto";

export interface User {
  id: string;
  name: string;
  email: string;
}

export type CreateUserInput = Omit<User, "id">;
export type UpdateUserInput = Partial<Omit<User, "id">>;

export class UserService {
  private store: Map<string, User> = new Map();

  create(input: CreateUserInput): User {
    if (!input.name || !input.email) {
      throw new Error("name and email are required");
    }
    const user: User = {
      id: randomUUID(),
      name: input.name,
      email: input.email,
    };
    this.store.set(user.id, user);
    return user;
  }

  getById(id: string): User {
    const user = this.store.get(id);
    if (!user) {
      throw new Error(`User not found: ${id}`);
    }
    return user;
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: string, input: UpdateUserInput): User {
    const existing = this.getById(id);
    const updated: User = {
      ...existing,
      ...(input.name !== undefined && { name: input.name }),
      ...(input.email !== undefined && { email: input.email }),
    };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.store.has(id)) {
      throw new Error(`User not found: ${id}`);
    }
    this.store.delete(id);
  }
}

/**
 * Project Service
 * Owns the project data store. Performs CRUD operations and manages membership.
 * Publishes no events. Subscribes to no events.
 */

import { randomUUID } from "crypto";

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type CreateProjectInput = Omit<Project, "id" | "memberIds"> & {
  memberIds?: string[];
};
export type UpdateProjectInput = Partial<Omit<Project, "id" | "memberIds">>;

export class ProjectService {
  private store: Map<string, Project> = new Map();

  create(input: CreateProjectInput): Project {
    if (!input.name) {
      throw new Error("name is required");
    }
    const project: Project = {
      id: randomUUID(),
      name: input.name,
      description: input.description ?? "",
      memberIds: input.memberIds ? [...input.memberIds] : [],
    };
    this.store.set(project.id, project);
    return project;
  }

  getById(id: string): Project {
    const project = this.store.get(id);
    if (!project) {
      throw new Error(`Project not found: ${id}`);
    }
    return project;
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(id: string, input: UpdateProjectInput): Project {
    const existing = this.getById(id);
    const updated: Project = {
      ...existing,
      ...(input.name !== undefined && { name: input.name }),
      ...(input.description !== undefined && { description: input.description }),
    };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.store.has(id)) {
      throw new Error(`Project not found: ${id}`);
    }
    this.store.delete(id);
  }

  addMember(id: string, userId: string): Project {
    const project = this.getById(id);
    if (project.memberIds.includes(userId)) {
      return project; // already a member, idempotent
    }
    const updated: Project = {
      ...project,
      memberIds: [...project.memberIds, userId],
    };
    this.store.set(id, updated);
    return updated;
  }

  removeMember(id: string, userId: string): Project {
    const project = this.getById(id);
    const updated: Project = {
      ...project,
      memberIds: project.memberIds.filter((mid) => mid !== userId),
    };
    this.store.set(id, updated);
    return updated;
  }
}

/**
 * Task Service
 * Owns the task data store. Enforces forward-only status transitions.
 * Publishes: task.assigned, task.statusChanged
 * Subscribes to no events.
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus";

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export type CreateTaskInput = {
  title: string;
  description?: string;
  projectId: string;
  assigneeId?: string | null;
};

export type UpdateTaskInput = Partial<
  Pick<Task, "title" | "description">
>;

// Defines the valid forward-only progression
const STATUS_ORDER: TaskStatus[] = ["todo", "in-progress", "done"];

export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export class TaskService {
  private store: Map<string, Task> = new Map();

  constructor(private readonly eventBus: EventBus) {}

  create(input: CreateTaskInput): Task {
    if (!input.title) {
      throw new Error("title is required");
    }
    if (!input.projectId) {
      throw new Error("projectId is required");
    }
    const task: Task = {
      id: randomUUID(),
      title: input.title,
      description: input.description ?? "",
      status: "todo",
      assigneeId: input.assigneeId ?? null,
      projectId: input.projectId,
    };
    this.store.set(task.id, task);
    return task;
  }

  getById(id: string): Task {
    const task = this.store.get(id);
    if (!task) {
      throw new Error(`Task not found: ${id}`);
    }
    return task;
  }

  getAll(): Task[] {
    return Array.from(this.store.values());
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter(
      (t) => t.projectId === projectId
    );
  }

  update(id: string, input: UpdateTaskInput): Task {
    const existing = this.getById(id);
    const updated: Task = {
      ...existing,
      ...(input.title !== undefined && { title: input.title }),
      ...(input.description !== undefined && { description: input.description }),
    };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): void {
    if (!this.store.has(id)) {
      throw new Error(`Task not found: ${id}`);
    }
    this.store.delete(id);
  }

  assign(id: string, assigneeId: string): Task {
    const task = this.getById(id);
    const updated: Task = { ...task, assigneeId };
    this.store.set(id, updated);

    const payload: TaskAssignedPayload = {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId,
    };
    this.eventBus.publish("task.assigned", payload);

    return updated;
  }

  changeStatus(id: string, newStatus: TaskStatus): Task {
    const task = this.getById(id);
    const currentIndex = STATUS_ORDER.indexOf(task.status);
    const nextIndex = STATUS_ORDER.indexOf(newStatus);

    if (nextIndex === -1) {
      throw new Error(`Invalid status: ${newStatus}`);
    }
    if (nextIndex <= currentIndex) {
      throw new Error(
        `Invalid status transition: "${task.status}" → "${newStatus}". Only forward transitions are allowed (todo → in-progress → done).`
      );
    }
    if (nextIndex !== currentIndex + 1) {
      throw new Error(
        `Invalid status transition: "${task.status}" → "${newStatus}". Statuses must be advanced one step at a time.`
      );
    }

    const oldStatus = task.status;
    const updated: Task = { ...task, status: newStatus };
    this.store.set(id, updated);

    const payload: TaskStatusChangedPayload = {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    };
    this.eventBus.publish("task.statusChanged", payload);

    return updated;
  }
}

/**
 * Comment Service
 * Owns the comment data store.
 * Publishes: comment.added
 * Subscribes to no events.
 *
 * NOTE: To publish comment.added with taskTitle and authorName, the router
 * must pass those enriched values in at call time — the service itself does
 * NOT reach into other services' stores (per ADR-002).
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus";

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export type CreateCommentInput = {
  taskId: string;
  authorId: string;
  body: string;
  /** Enriched fields supplied by the router for the event payload */
  taskTitle: string;
  authorName: string;
};

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

export class CommentService {
  private store: Map<string, Comment> = new Map();

  constructor(private readonly eventBus: EventBus) {}

  create(input: CreateCommentInput): Comment {
    if (!input.taskId) throw new Error("taskId is required");
    if (!input.authorId) throw new Error("authorId is required");
    if (!input.body) throw new Error("body is required");

    const comment: Comment = {
      id: randomUUID(),
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body,
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);

    const payload: CommentAddedPayload = {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: input.taskTitle,
      authorId: comment.authorId,
      authorName: input.authorName,
    };
    this.eventBus.publish("comment.added", payload);

    return comment;
  }

  getById(id: string): Comment {
    const comment = this.store.get(id);
    if (!comment) {
      throw new Error(`Comment not found: ${id}`);
    }
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter(
      (c) => c.taskId === taskId
    );
  }

  delete(id: string): void {
    if (!this.store.has(id)) {
      throw new Error(`Comment not found: ${id}`);
    }
    this.store.delete(id);
  }
}

/**
 * Notification Service
 * Owns the notification data store.
 * Publishes no events.
 * Subscribes to: task.assigned, task.statusChanged, comment.added
 */

import { randomUUID } from "crypto";
import { EventBus } from "../event-bus";
import {
  TaskAssignedPayload,
  TaskStatusChangedPayload,
} from "./task-service";
import { CommentAddedPayload } from "./comment-service";

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

export class NotificationService {
  private store: Map<string, Notification> = new Map();

  constructor(private readonly eventBus: EventBus) {
    this.registerSubscriptions();
  }

  // ── Internal helpers ───────────────────────────────────────────────────────

  private registerSubscriptions(): void {
    this.eventBus.subscribe("task.assigned", (payload) => {
      const { taskId, taskTitle, assigneeId } =
        payload as TaskAssignedPayload;
      this.createNotification(
        assigneeId,
        `You have been assigned to task "${taskTitle}" (${taskId}).`
      );
    });

    this.eventBus.subscribe("task.statusChanged", (payload) => {
      const { taskId, taskTitle, assigneeId, oldStatus, newStatus } =
        payload as TaskStatusChangedPayload;
      if (!assigneeId) return; // no assignee — nothing to notify
      this.createNotification(
        assigneeId,
        `Task "${taskTitle}" (${taskId}) status changed from "${oldStatus}" to "${newStatus}".`
      );
    });

    this.eventBus.subscribe("comment.added", (payload) => {
      const { commentId, taskId, taskTitle, authorId, authorName } =
        payload as CommentAddedPayload;
      // Notify the task's assignee — but the service only knows what the event
      // carries. The comment.added payload does NOT include assigneeId because
      // the Comment Service doesn't own Task data. Instead, the router enriches
      // the payload via a separate notification created there — OR we require
      // the router to pass assigneeId in an extended payload.
      //
      // Per the spec, comment.added carries: commentId, taskId, taskTitle,
      // authorId, authorName — no assigneeId. We therefore notify the AUTHOR
      // as an acknowledgement, and rely on the router to separately trigger
      // a notification for the assignee when it knows both.
      //
      // To stay spec-compliant without cross-service coupling, we create a
      // self-notification for the author (comment submitted successfully) and
      // expose a public helper so the router can create the assignee notification.
      void commentId; // used in message below
      this.createNotification(
        authorId,
        `Your comment on task "${taskTitle}" (${taskId}) was posted by ${authorName}.`
      );
    });
  }

  private createNotification(userId: string, message: string): Notification {
    const notification: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notification.id, notification);
    return notification;
  }

  // ── Public API ─────────────────────────────────────────────────────────────

  /**
   * Called by the router to directly create a notification for a specific user
   * (e.g., notify the task assignee when a comment is added — the router knows
   * the assignee because it already resolved the task, without the service
   * needing to call into TaskService).
   */
  createForUser(userId: string, message: string): Notification {
    return this.createNotification(userId, message);
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values()).filter(
      (n) => n.userId === userId
    );
  }

  markAsRead(id: string): Notification {
    const notification = this.store.get(id);
    if (!notification) {
      throw new Error(`Notification not found: ${id}`);
    }
    const updated: Notification = { ...notification, read: true };
    this.store.set(id, updated);
    return updated;
  }
}

/**
 * API Router
 * Single HTTP entry point. Parses requests, delegates to services, returns JSON.
 * Uses Node.js built-in `http` module only.
 */

import { IncomingMessage, ServerResponse } from "http";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService, TaskStatus } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";

// ── Helpers ──────────────────────────────────────────────────────────────────

function readBody(req: IncomingMessage): Promise<unknown> {
  return new Promise((resolve, reject) => {
    let raw = "";
    req.on("data", (chunk: Buffer) => (raw += chunk.toString()));
    req.on("end", () => {
      if (!raw.trim()) {
        resolve({});
        return;
      }
      try {
        resolve(JSON.parse(raw));
      } catch {
        reject(new Error("Invalid JSON body"));
      }
    });
    req.on("error", reject);
  });
}

function send(
  res: ServerResponse,
  statusCode: number,
  body: unknown
): void {
  const json = JSON.stringify(body, null, 2);
  res.writeHead(statusCode, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(json),
  });
  res.end(json);
}

function sendError(res: ServerResponse, statusCode: number, message: string): void {
  send(res, statusCode, { error: message });
}

/** Parse path segments and query string from the raw URL. */
function parsePath(req: IncomingMessage): {
  segments: string[];
  query: Record<string, string>;
} {
  const rawUrl = req.url ?? "/";
  const [pathPart, queryPart] = rawUrl.split("?");
  const segments = pathPart.split("/").filter(Boolean);
  const query: Record<string, string> = {};
  if (queryPart) {
    for (const pair of queryPart.split("&")) {
      const [k, v] = pair.split("=");
      if (k) query[decodeURIComponent(k)] = decodeURIComponent(v ?? "");
    }
  }
  return { segments, query };
}

// ── Router class ─────────────────────────────────────────────────────────────

export class Router {
  constructor(
    private readonly users: UserService,
    private readonly projects: ProjectService,
    private readonly tasks: TaskService,
    private readonly comments: CommentService,
    private readonly notifications: NotificationService
  ) {}

  async handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
    try {
      const method = req.method ?? "GET";
      const { segments, query } = parsePath(req);
      const [resource, id, subResource] = segments;

      // ── /users ──────────────────────────────────────────────────────────────
      if (resource === "users") {
        if (!id) {
          if (method === "GET") {
            return send(res, 200, this.users.getAll());
          }
          if (method === "POST") {
            const body = await readBody(req) as Record<string, unknown>;
            const user = this.users.create({
              name: body.name as string,
              email: body.email as string,
            });
            return send(res, 201, user);
          }
        } else {
          if (method === "GET") {
            const user = this.users.getById(id);
            return send(res, 200, user);
          }
          if (method === "PUT") {
            const body = await readBody(req) as Record<string, unknown>;
            const user = this.users.update(id, {
              name: body.name as string | undefined,
              email: body.email as string | undefined,
            });
            return send(res, 200, user);
          }
          if (method === "DELETE") {
            this.users.delete(id);
            return send(res, 200, { message: "User deleted" });
          }
        }
      }

      // ── /projects ───────────────────────────────────────────────────────────
      if (resource === "projects") {
        if (!id) {
          if (method === "GET") {
            return send(res, 200, this.projects.getAll());
          }
          if (method === "POST") {
            const body = await readBody(req) as Record<string, unknown>;
            const project = this.projects.create({
              name: body.name as string,
              description: (body.description as string | undefined) ?? "",
              memberIds: (body.memberIds as string[] | undefined) ?? [],
            });
            return send(res, 201, project);
          }
        } else if (!subResource) {
          if (method === "GET") {
            return send(res, 200, this.projects.getById(id));
          }
          if (method === "PUT") {
            const body = await readBody(req) as Record<string, unknown>;
            const project = this.projects.update(id, {
              name: body.name as string | undefined,
              description: body.description as string | undefined,
            });
            return send(res, 200, project);
          }
          if (method === "DELETE") {
            this.projects.delete(id);
            return send(res, 200, { message: "Project deleted" });
          }
        } else if (subResource === "members") {
          if (method === "POST") {
            const body = await readBody(req) as Record<string, unknown>;
            const userId = body.userId as string;
            if (!userId) return sendError(res, 400, "userId is required");
            const project = this.projects.addMember(id, userId);
            return send(res, 200, project);
          }
          if (method === "DELETE") {
            const body = await readBody(req) as Record<string, unknown>;
            const userId = body.userId as string;
            if (!userId) return sendError(res, 400, "userId is required");
            const project = this.projects.removeMember(id, userId);
            return send(res, 200, project);
          }
        }
      }

      // ── /tasks ──────────────────────────────────────────────────────────────
      if (resource === "tasks") {
        if (!id) {
          if (method === "GET") {
            if (query.projectId) {
              return send(res, 200, this.tasks.getByProject(query.projectId));
            }
            return send(res, 200, this.tasks.getAll());
          }
          if (method === "POST") {
            const body = await readBody(req) as Record<string, unknown>;
            const task = this.tasks.create({
              title: body.title as string,
              description: body.description as string | undefined,
              projectId: body.projectId as string,
              assigneeId: body.assigneeId as string | null | undefined,
            });
            return send(res, 201, task);
          }
        } else if (!subResource) {
          if (method === "GET") {
            return send(res, 200, this.tasks.getById(id));
          }
          if (method === "PUT") {
            const body = await readBody(req) as Record<string, unknown>;
            const task = this.tasks.update(id, {
              title: body.title as string | undefined,
              description: body.description as string | undefined,
            });
            return send(res, 200, task);
          }
          if (method === "DELETE") {
            this.tasks.delete(id);
            return send(res, 200, { message: "Task deleted" });
          }
        } else if (subResource === "status") {
          if (method === "PUT") {
            const body = await readBody(req) as Record<string, unknown>;
            const status = body.status as TaskStatus;
            if (!status) return sendError(res, 400, "status is required");
            const task = this.tasks.changeStatus(id, status);
            return send(res, 200, task);
          }
        } else if (subResource === "assign") {
          if (method === "PUT") {
            const body = await readBody(req) as Record<string, unknown>;
            const assigneeId = body.assigneeId as string;
            if (!assigneeId) return sendError(res, 400, "assigneeId is required");
            const task = this.tasks.assign(id, assigneeId);
            return send(res, 200, task);
          }
        }
      }

      // ── /comments ───────────────────────────────────────────────────────────
      if (resource === "comments") {
        if (!id) {
          if (method === "GET") {
            if (query.taskId) {
              return send(res, 200, this.comments.getByTask(query.taskId));
            }
            return sendError(res, 400, "taskId query parameter is required");
          }
          if (method === "POST") {
            const body = await readBody(req) as Record<string, unknown>;
            const taskId = body.taskId as string;
            const authorId = body.authorId as string;
            const commentBody = body.body as string;

            // Router resolves enriched data (task title, author name) so that
            // neither CommentService nor NotificationService needs to cross
            // service boundaries — satisfying ADR-001 and ADR-002.
            const task = this.tasks.getById(taskId);
            const author = this.users.getById(authorId);

            const comment = this.comments.create({
              taskId,
              authorId,
              body: commentBody,
              taskTitle: task.title,
              authorName: author.name,
            });

            // Notify the task's assignee about the new comment (if there is
            // one and it's not the commenter themselves).
            if (task.assigneeId && task.assigneeId !== authorId) {
              this.notifications.createForUser(
                task.assigneeId,
                `${author.name} commented on task "${task.title}" (${task.id}): "${commentBody.slice(0, 80)}"`
              );
            }

            return send(res, 201, comment);
          }
        } else {
          if (method === "GET") {
            return send(res, 200, this.comments.getById(id));
          }
          if (method === "DELETE") {
            this.comments.delete(id);
            return send(res, 200, { message: "Comment deleted" });
          }
        }
      }

      // ── /notifications ──────────────────────────────────────────────────────
      if (resource === "notifications") {
        if (!id) {
          if (method === "GET") {
            if (!query.userId) {
              return sendError(res, 400, "userId query parameter is required");
            }
            return send(res, 200, this.notifications.getByUser(query.userId));
          }
        } else if (!subResource) {
          // no bare /notifications/:id endpoint in spec — fall through to 404
        } else if (subResource === "read") {
          if (method === "PUT") {
            const notification = this.notifications.markAsRead(id);
            return send(res, 200, notification);
          }
        }
      }

      // ── 404 ─────────────────────────────────────────────────────────────────
      sendError(res, 404, `Cannot ${method} /${segments.join("/")}`);
    } catch (err) {
      const message = err instanceof Error ? err.message : "Internal server error";
      // Distinguish "not found" style errors from true 500s
      if (
        message.startsWith("User not found") ||
        message.startsWith("Project not found") ||
        message.startsWith("Task not found") ||
        message.startsWith("Comment not found") ||
        message.startsWith("Notification not found")
      ) {
        sendError(res, 404, message);
      } else if (message.startsWith("Invalid status transition") || message.startsWith("Invalid status")) {
        sendError(res, 422, message);
      } else if (message.includes("is required") || message === "Invalid JSON body") {
        sendError(res, 400, message);
      } else {
        sendError(res, 500, message);
      }
    }
  }
}

/**
 * Entry Point
 * Wires all services together, registers event subscriptions, starts the HTTP server.
 */

import { createServer } from "http";
import { EventBus } from "./event-bus";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";
import { Router } from "./router";

const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

// 1. Create the event bus (shared communication channel)
const eventBus = new EventBus();

// 2. Instantiate services — each receives the event bus if it needs it
const userService = new UserService();
const projectService = new ProjectService();
const taskService = new TaskService(eventBus);
const commentService = new CommentService(eventBus);
// NotificationService registers its event subscriptions in its constructor
const notificationService = new NotificationService(eventBus);

// 3. Wire up the router with all services
const router = new Router(
  userService,
  projectService,
  taskService,
  commentService,
  notificationService
);

// 4. Create and start the HTTP server
const server = createServer((req, res) => {
  router.handle(req, res).catch((err: unknown) => {
    const message =
      err instanceof Error ? err.message : "Unexpected server error";
    console.error("[server error]", message);
    if (!res.headersSent) {
      res.writeHead(500, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: message }));
    }
  });
});

server.listen(PORT, () => {
  console.log(`Task Management API listening on http://localhost:${PORT}`);
});

export { server, eventBus, userService, projectService, taskService, commentService, notificationService };

/**
 * Demo Script
 * Starts the server programmatically and exercises every API endpoint,
 * validating the end-to-end flow described in the architecture spec.
 *
 * Run with: npx tsx src/demo.ts
 */

import { createServer } from "http";
import { EventBus } from "./event-bus";
import { UserService } from "./services/user-service";
import { ProjectService } from "./services/project-service";
import { TaskService } from "./services/task-service";
import { CommentService } from "./services/comment-service";
import { NotificationService } from "./services/notification-service";
import { Router } from "./router";

// ── Colour helpers (ANSI) ────────────────────────────────────────────────────
const C = {
  reset: "\x1b[0m",
  bold: "\x1b[1m",
  green: "\x1b[32m",
  yellow: "\x1b[33m",
  cyan: "\x1b[36m",
  red: "\x1b[31m",
  grey: "\x1b[90m",
};

function heading(text: string): void {
  console.log(`\n${C.bold}${C.cyan}══ ${text} ══${C.reset}`);
}

function ok(label: string, value?: unknown): void {
  const extra =
    value !== undefined ? `${C.grey} → ${JSON.stringify(value)}${C.reset}` : "";
  console.log(`  ${C.green}✓${C.reset} ${label}${extra}`);
}

function fail(label: string, reason: string): void {
  console.log(`  ${C.red}✗${C.reset} ${label}: ${reason}`);
}

function info(label: string, value: unknown): void {
  console.log(
    `  ${C.yellow}·${C.reset} ${label}: ${C.grey}${JSON.stringify(value, null, 2)
      .split("\n")
      .join("\n    ")}${C.reset}`
  );
}

// ── HTTP helper ──────────────────────────────────────────────────────────────
const DEMO_PORT = 3001;
const BASE = `http://localhost:${DEMO_PORT}`;

async function req<T = unknown>(
  method: string,
  path: string,
  body?: unknown
): Promise<{ status: number; data: T }> {
  const url = `${BASE}${path}`;
  const options: Parameters<typeof import("http").request>[1] = {
    method,
    headers: { "Content-Type": "application/json" },
  };

  return new Promise((resolve, reject) => {
    const http = require("http") as typeof import("http");
    const parsedUrl = new URL(url);
    const reqOptions = {
      hostname: parsedUrl.hostname,
      port: parseInt(parsedUrl.port, 10),
      path: parsedUrl.pathname + (parsedUrl.search ?? ""),
      method,
      headers: { "Content-Type": "application/json" },
    };
    const request = http.request(reqOptions, (res) => {
      let raw = "";
      res.on("data", (chunk: Buffer) => (raw += chunk.toString()));
      res.on("end", () => {
        try {
          resolve({ status: res.statusCode ?? 0, data: JSON.parse(raw) as T });
        } catch {
          reject(new Error(`Failed to parse response: ${raw}`));
        }
      });
    });
    request.on("error", reject);
    if (body !== undefined) {
      request.write(JSON.stringify(body));
    }
    request.end();
  });

  void options; // suppress unused warning
}

// ── Main demo ────────────────────────────────────────────────────────────────
async function runDemo(): Promise<void> {
  // ── Boot a fresh server ───────────────────────────────────────────────────
  const eventBus = new EventBus();
  const userService = new UserService();
  const projectService = new ProjectService();
  const taskService = new TaskService(eventBus);
  const commentService = new CommentService(eventBus);
  const notificationService = new NotificationService(eventBus);
  const router = new Router(
    userService,
    projectService,
    taskService,
    commentService,
    notificationService
  );

  const server = createServer((req, res) => {
    router.handle(req, res).catch((err: unknown) => {
      const msg = err instanceof Error ? err.message : "error";
      if (!res.headersSent) {
        res.writeHead(500, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: msg }));
      }
    });
  });

  await new Promise<void>((resolve) => server.listen(DEMO_PORT, resolve));
  console.log(
    `${C.bold}Task Management API Demo${C.reset} — server on port ${DEMO_PORT}\n`
  );

  let passed = 0;
  let failed = 0;

  function assert(
    label: string,
    condition: boolean,
    extra?: unknown
  ): void {
    if (condition) {
      ok(label, extra);
      passed++;
    } else {
      fail(label, `assertion failed — got ${JSON.stringify(extra)}`);
      failed++;
    }
  }

  try {
    // ── 1. Create users ─────────────────────────────────────────────────────
    heading("1. Create Users");

    const { data: alice } = await req<{ id: string; name: string; email: string }>(
      "POST",
      "/users",
      { name: "Alice", email: "alice@example.com" }
    );
    assert("Create Alice", !!alice.id && alice.name === "Alice", alice);

    const { data: bob } = await req<{ id: string; name: string; email: string }>(
      "POST",
      "/users",
      { name: "Bob", email: "bob@example.com" }
    );
    assert("Create Bob", !!bob.id && bob.name === "Bob", bob);

    const { data: allUsers } = await req<unknown[]>("GET", "/users");
    assert("GET /users returns 2 users", allUsers.length === 2);

    const { data: fetchedAlice } = await req<{ id: string; name: string }>(
      "GET",
      `/users/${alice.id}`
    );
    assert("GET /users/:id returns Alice", fetchedAlice.name === "Alice");

    const { data: updatedAlice } = await req<{ name: string }>(
      "PUT",
      `/users/${alice.id}`,
      { name: "Alice A." }
    );
    assert("PUT /users/:id updates name", updatedAlice.name === "Alice A.");

    // ── 2. Create project ───────────────────────────────────────────────────
    heading("2. Create Project");

    const { data: project } = await req<{ id: string; name: string; memberIds: string[] }>(
      "POST",
      "/projects",
      { name: "Alpha", description: "The first project" }
    );
    assert("Create project Alpha", !!project.id && project.name === "Alpha", project);

    const { data: allProjects } = await req<unknown[]>("GET", "/projects");
    assert("GET /projects returns 1 project", allProjects.length === 1);

    const { data: updatedProject } = await req<{ description: string }>(
      "PUT",
      `/projects/${project.id}`,
      { description: "Updated description" }
    );
    assert("PUT /projects/:id updates description", updatedProject.description === "Updated description");

    // ── 3. Add members to project ───────────────────────────────────────────
    heading("3. Add Members to Project");

    const { data: projWithAlice } = await req<{ memberIds: string[] }>(
      "POST",
      `/projects/${project.id}/members`,
      { userId: alice.id }
    );
    assert("Add Alice to project", projWithAlice.memberIds.includes(alice.id), projWithAlice.memberIds);

    const { data: projWithBoth } = await req<{ memberIds: string[] }>(
      "POST",
      `/projects/${project.id}/members`,
      { userId: bob.id }
    );
    assert("Add Bob to project", projWithBoth.memberIds.includes(bob.id), projWithBoth.memberIds);
    assert("Project has 2 members", projWithBoth.memberIds.length === 2);

    // Idempotent add
    const { data: projIdempotent } = await req<{ memberIds: string[] }>(
      "POST",
      `/projects/${project.id}/members`,
      { userId: alice.id }
    );
    assert("Adding Alice again is idempotent", projIdempotent.memberIds.length === 2);

    const { data: projAfterRemove } = await req<{ memberIds: string[] }>(
      "DELETE",
      `/projects/${project.id}/members`,
      { userId: bob.id }
    );
    assert("Remove Bob from project", !projAfterRemove.memberIds.includes(bob.id));

    // Re-add Bob for subsequent steps
    await req("POST", `/projects/${project.id}/members`, { userId: bob.id });

    // ── 4. Create tasks ─────────────────────────────────────────────────────
    heading("4. Create Tasks");

    const { data: task1 } = await req<{ id: string; title: string; status: string; assigneeId: string | null }>(
      "POST",
      "/tasks",
      { title: "Design schema", description: "Create DB schema", projectId: project.id }
    );
    assert("Create task1 (Design schema)", task1.status === "todo" && task1.assigneeId === null, task1);

    const { data: task2 } = await req<{ id: string; title: string; status: string }>(
      "POST",
      "/tasks",
      { title: "Implement API", projectId: project.id }
    );
    assert("Create task2 (Implement API)", !!task2.id && task2.status === "todo");

    const { data: tasksForProject } = await req<unknown[]>(
      "GET",
      `/tasks?projectId=${project.id}`
    );
    assert("GET /tasks?projectId returns 2 tasks", tasksForProject.length === 2);

    const { data: fetchedTask } = await req<{ title: string }>(
      "GET",
      `/tasks/${task1.id}`
    );
    assert("GET /tasks/:id returns task1", fetchedTask.title === "Design schema");

    const { data: updatedTask } = await req<{ title: string }>(
      "PUT",
      `/tasks/${task1.id}`,
      { title: "Design DB schema" }
    );
    assert("PUT /tasks/:id updates title", updatedTask.title === "Design DB schema");

    // ── 5. Assign tasks ─────────────────────────────────────────────────────
    heading("5. Assign Tasks → triggers notifications");

    const { status: assignStatus, data: assignedTask } = await req<{
      id: string;
      assigneeId: string;
    }>("PUT", `/tasks/${task1.id}/assign`, { assigneeId: alice.id });
    assert("PUT /tasks/:id/assign returns 200", assignStatus === 200);
    assert("Task1 assignee is Alice", assignedTask.assigneeId === alice.id);

    await req("PUT", `/tasks/${task2.id}/assign`, { assigneeId: bob.id });
    ok("Assigned task2 to Bob");

    // Verify Alice got a notification
    const { data: aliceNotifs1 } = await req<
      Array<{ id: string; message: string; read: boolean; userId: string }>
    >("GET", `/notifications?userId=${alice.id}`);
    assert(
      "Alice received task.assigned notification",
      aliceNotifs1.some((n) => n.message.includes("Design DB schema"))
    );
    info("Alice notifications after assignment", aliceNotifs1.map((n) => n.message));

    // ── 6. Change task status ───────────────────────────────────────────────
    heading("6. Change Task Status (forward-only)");

    const { data: inProgress } = await req<{ status: string }>(
      "PUT",
      `/tasks/${task1.id}/status`,
      { status: "in-progress" }
    );
    assert("Task1 moved to in-progress", inProgress.status === "in-progress");

    // Verify notification for status change
    const { data: aliceNotifs2 } = await req<Array<{ message: string }>>(
      "GET",
      `/notifications?userId=${alice.id}`
    );
    assert(
      "Alice received task.statusChanged notification",
      aliceNotifs2.some((n) => n.message.includes("in-progress"))
    );

    const { data: done } = await req<{ status: string }>(
      "PUT",
      `/tasks/${task1.id}/status`,
      { status: "done" }
    );
    assert("Task1 moved to done", done.status === "done");

    // Attempt backward transition — must fail
    const { status: backStatus, data: backErr } = await req<{ error: string }>(
      "PUT",
      `/tasks/${task1.id}/status`,
      { status: "todo" }
    );
    assert(
      "Backward transition is rejected (422)",
      backStatus === 422,
      (backErr as { error: string }).error
    );

    // Attempt skip transition on task2 (todo → done)
    const { status: skipStatus, data: skipErr } = await req<{ error: string }>(
      "PUT",
      `/tasks/${task2.id}/status`,
      { status: "done" }
    );
    assert(
      "Skipping a status step is rejected (422)",
      skipStatus === 422,
      (skipErr as { error: string }).error
    );

    // ── 7. Add comments ─────────────────────────────────────────────────────
    heading("7. Add Comments → triggers notifications");

    const { status: commentStatus, data: comment1 } = await req<{
      id: string;
      taskId: string;
      authorId: string;
      body: string;
      createdAt: string;
    }>("POST", "/comments", {
      taskId: task1.id,
      authorId: bob.id,
      body: "Great work on the schema!",
    });
    assert("POST /comments returns 201", commentStatus === 201);
    assert("Comment linked to task1", comment1.taskId === task1.id);

    // Alice is assignee of task1, Bob is commenter → Alice should be notified
    const { data: aliceNotifs3 } = await req<Array<{ message: string }>>(
      "GET",
      `/notifications?userId=${alice.id}`
    );
    assert(
      "Alice notified of Bob's comment on her task",
      aliceNotifs3.some((n) => n.message.includes("Bob") && n.message.includes("commented"))
    );

    const { data: comment2 } = await req<{ id: string }>("POST", "/comments", {
      taskId: task2.id,
      authorId: alice.id,
      body: "Let me know if you need help.",
    });
    assert("Second comment created", !!comment2.id);

    // GET /comments?taskId
    const { data: task1Comments } = await req<unknown[]>(
      "GET",
      `/comments?taskId=${task1.id}`
    );
    assert("GET /comments?taskId returns 1 comment for task1", task1Comments.length === 1);

    const { data: fetchedComment } = await req<{ body: string }>(
      "GET",
      `/comments/${comment1.id}`
    );
    assert("GET /comments/:id returns correct comment", fetchedComment.body === "Great work on the schema!");

    // ── 8. Check all notifications ──────────────────────────────────────────
    heading("8. Check Notifications");

    const { data: allAliceNotifs } = await req<
      Array<{ id: string; message: string; read: boolean }>
    >("GET", `/notifications?userId=${alice.id}`);
    info("All Alice notifications", allAliceNotifs.map((n) => ({ msg: n.message, read: n.read })));

    const { data: bobNotifs } = await req<
      Array<{ id: string; message: string; read: boolean }>
    >("GET", `/notifications?userId=${bob.id}`);
    info("All Bob notifications", bobNotifs.map((n) => ({ msg: n.message, read: n.read })));

    // ── 9. Mark notification as read ────────────────────────────────────────
    heading("9. Mark Notification as Read");

    if (allAliceNotifs.length > 0) {
      const firstNotifId = allAliceNotifs[0].id;
      const { data: readNotif } = await req<{ read: boolean }>(
        "PUT",
        `/notifications/${firstNotifId}/read`
      );
      assert("Notification marked as read", readNotif.read === true);
    }

    // ── 10. Delete operations ───────────────────────────────────────────────
    heading("10. Delete Operations");

    const { data: deleteComment } = await req(
      "DELETE",
      `/comments/${comment1.id}`
    );
    assert("DELETE /comments/:id", (deleteComment as { message: string }).message === "Comment deleted");

    // Create a throwaway task to delete
    const { data: throwaway } = await req<{ id: string }>("POST", "/tasks", {
      title: "Throwaway",
      projectId: project.id,
    });
    const { data: deleteTask } = await req("DELETE", `/tasks/${throwaway.id}`);
    assert("DELETE /tasks/:id", (deleteTask as { message: string }).message === "Task deleted");

    // Create throwaway user to delete
    const { data: throwawayUser } = await req<{ id: string }>("POST", "/users", {
      name: "Temp",
      email: "temp@example.com",
    });
    const { data: deleteUser } = await req("DELETE", `/users/${throwawayUser.id}`);
    assert("DELETE /users/:id", (deleteUser as { message: string }).message === "User deleted");

    // Create throwaway project to delete
    const { data: throwawayProject } = await req<{ id: string }>("POST", "/projects", {
      name: "Temp Project",
      description: "",
    });
    const { data: deleteProject } = await req("DELETE", `/projects/${throwawayProject.id}`);
    assert("DELETE /projects/:id", (deleteProject as { message: string }).message === "Project deleted");

    // ── 11. Error cases ─────────────────────────────────────────────────────
    heading("11. Error Cases");

    const { status: s404 } = await req("GET", "/users/nonexistent-id");
    assert("GET /users/:id with bad id → 404", s404 === 404);

    const { status: s400 } = await req("POST", "/users", { email: "no-name@x.com" });
    assert("POST /users without name → 400", s400 === 400);

    const { status: sMissing } = await req("GET", "/notifications");
    assert("GET /notifications without userId → 400", sMissing === 400);

    const { status: s404Route } = await req("GET", "/unknown-route");
    assert("Unknown route → 404", s404Route === 404);

  } finally {
    // ── Summary ────────────────────────────────────────────────────────────
    console.log(`\n${C.bold}Results: ${C.green}${passed} passed${C.reset}${C.bold}, ${failed > 0 ? C.red : C.grey}${failed} failed${C.reset}\n`);
    server.close();
  }
}

runDemo().catch((err) => {
  console.error("Demo failed:", err);
  process.exit(1);
});

